changeSet.sql:
CREATE SEQUENCE IF NOT EXISTS seq_unipost_record_audit_log START WITH 1 INCREMENT BY 1;

CREATE TABLE IF NOT EXISTS UNIPOST_RECORD_AUDIT_LOG (
    id BIGINT NOT NULL DEFAULT nextval('seq_unipost_record_audit_log'),
    tenant_id VARCHAR(64) NOT NULL,
    record_id BIGINT NOT NULL,
    entity_type_id BIGINT NOT NULL,
    operation VARCHAR(16) NOT NULL,
    actor VARCHAR(64) NOT NULL,
    version BIGINT NOT NULL,
    old_attributes JSONB NULL,
    new_attributes JSONB NULL,
    delta JSONB NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
    PRIMARY KEY (id, created_at)
) PARTITION BY RANGE (created_at);

-- Initial Default and Rolling Monthly Partitions
CREATE TABLE IF NOT EXISTS unipost_record_audit_log_default 
    PARTITION OF UNIPOST_RECORD_AUDIT_LOG DEFAULT;

CREATE TABLE IF NOT EXISTS unipost_record_audit_log_2026_10 
    PARTITION OF UNIPOST_RECORD_AUDIT_LOG 
    FOR VALUES FROM ('2026-10-01 00:00:00+00') TO ('2026-11-01 00:00:00+00');

CREATE TABLE IF NOT EXISTS unipost_record_audit_log_2026_11 
    PARTITION OF UNIPOST_RECORD_AUDIT_LOG 
    FOR VALUES FROM ('2026-11-01 00:00:00+00') TO ('2026-12-01 00:00:00+00');

CREATE TABLE IF NOT EXISTS unipost_record_audit_log_2026_12 
    PARTITION OF UNIPOST_RECORD_AUDIT_LOG 
    FOR VALUES FROM ('2026-12-01 00:00:00+00') TO ('2027-01-01 00:00:00+00');

CREATE TABLE IF NOT EXISTS unipost_record_audit_log_2027_01 
    PARTITION OF UNIPOST_RECORD_AUDIT_LOG 
    FOR VALUES FROM ('2027-01-01 00:00:00+00') TO ('2027-02-01 00:00:00+00');

-- Composite Lookup Index
CREATE INDEX IF NOT EXISTS idx_record_audit_lookup 
    ON UNIPOST_RECORD_AUDIT_LOG (tenant_id, record_id, created_at DESC);

-- RLS Enablement & Tenant Isolation Policy
ALTER TABLE UNIPOST_RECORD_AUDIT_LOG ENABLE ROW LEVEL SECURITY;
ALTER TABLE UNIPOST_RECORD_AUDIT_LOG FORCE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS tenant_isolation_record_audit ON UNIPOST_RECORD_AUDIT_LOG;
CREATE POLICY tenant_isolation_record_audit ON UNIPOST_RECORD_AUDIT_LOG
    FOR ALL
    USING (
        current_setting('app.current_tenant_id', true) = 'SYSTEM'
        OR tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')
    )
    WITH CHECK (
        current_setting('app.current_tenant_id', true) = 'SYSTEM'
        OR tenant_id = NULLIF(current_setting('app.current_tenant_id', true), '')
    );
